fun <T> backtrack(
    path: MutableList<T>,
    result: MutableList<List<T>>
) {
    if (isSolution(path)) {
        result.add(ArrayList(path))               // copy, because path keeps changing
        return
    }
    for (choice in candidates(path)) {
        if (!isValid(path, choice)) continue      // prune
        path.add(choice)                          // choose
        backtrack(path, result)                   // explore
        path.removeAt(path.lastIndex)             // unchoose
    }
}
