fun subsets(nums: IntArray): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int) {
        result.add(ArrayList(path))               // every path is a valid subset
        for (i in start until nums.size) {
            path.add(nums[i])
            backtrack(i + 1)                      // next choices come only after i
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0)
    return result
}
// Time: O(n * 2^n)   Space: O(n) recursion plus the output

fun subsetsIncludeExclude(nums: IntArray): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun dfs(i: Int) {
        if (i == nums.size) {
            result.add(ArrayList(path))
            return
        }
        path.add(nums[i])                         // include nums[i]
        dfs(i + 1)
        path.removeAt(path.lastIndex)
        dfs(i + 1)                                // exclude nums[i]
    }

    dfs(0)
    return result
}
// Same answers, a binary decision tree of depth n

fun subsetsBitmask(nums: IntArray): List<List<Int>> {
    val n = nums.size
    val result = mutableListOf<List<Int>>()
    for (mask in 0 until (1 shl n)) {
        val subset = ArrayList<Int>()
        for (i in 0 until n) {
            if (mask and (1 shl i) != 0) subset.add(nums[i])
        }
        result.add(subset)
    }
    return result
}
// Time: O(n * 2^n)   Works for n up to about 20

fun subsetsWithDup(nums: IntArray): List<List<Int>> {
    nums.sort()                                   // equal values become neighbors
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int) {
        result.add(ArrayList(path))
        for (i in start until nums.size) {
            if (i > start && nums[i] == nums[i - 1]) continue   // skip a duplicate at the same level
            path.add(nums[i])
            backtrack(i + 1)
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0)
    return result
}
// Time: O(n * 2^n)   Space: O(n)

fun permute(nums: IntArray): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()
    val used = BooleanArray(nums.size)

    fun backtrack() {
        if (path.size == nums.size) {
            result.add(ArrayList(path))
            return
        }
        for (i in nums.indices) {
            if (used[i]) continue
            used[i] = true                        // choose
            path.add(nums[i])
            backtrack()                           // explore
            path.removeAt(path.lastIndex)         // unchoose
            used[i] = false
        }
    }

    backtrack()
    return result
}
// Time: O(n * n!)   Space: O(n)

fun permuteSwap(nums: IntArray): List<List<Int>> {
    val result = mutableListOf<List<Int>>()

    fun swap(i: Int, j: Int) {
        val t = nums[i]; nums[i] = nums[j]; nums[j] = t
    }

    fun backtrack(start: Int) {
        if (start == nums.size) {
            result.add(nums.toList())             // copy the current arrangement
            return
        }
        for (i in start until nums.size) {
            swap(start, i)                        // put nums[i] in position 'start'
            backtrack(start + 1)
            swap(start, i)                        // undo
        }
    }

    backtrack(0)
    return result
}
// Time: O(n * n!)   Space: O(n), no used array needed

fun permuteUnique(nums: IntArray): List<List<Int>> {
    nums.sort()
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()
    val used = BooleanArray(nums.size)

    fun backtrack() {
        if (path.size == nums.size) {
            result.add(ArrayList(path))
            return
        }
        for (i in nums.indices) {
            if (used[i]) continue
            // skip a duplicate unless its earlier twin is already in the path
            if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue
            used[i] = true
            path.add(nums[i])
            backtrack()
            path.removeAt(path.lastIndex)
            used[i] = false
        }
    }

    backtrack()
    return result
}
// Time: O(n * n!) worst case   Space: O(n)

fun combine(n: Int, k: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int) {
        if (path.size == k) {
            result.add(ArrayList(path))
            return
        }
        val need = k - path.size
        // prune: if fewer than 'need' numbers remain, this branch cannot finish
        for (i in start..n - need + 1) {
            path.add(i)
            backtrack(i + 1)
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(1)
    return result
}
// Time: O(k * C(n, k))   Space: O(k)

fun combinationSum(candidates: IntArray, target: Int): List<List<Int>> {
    candidates.sort()
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int, remaining: Int) {
        if (remaining == 0) {
            result.add(ArrayList(path))
            return
        }
        for (i in start until candidates.size) {
            if (candidates[i] > remaining) break          // sorted: every later value is too big as well
            path.add(candidates[i])
            backtrack(i, remaining - candidates[i])       // i, not i + 1: the same number may be reused
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0, target)
    return result
}
// Time: O(N^(T / M)) where T = target and M = smallest candidate   Space: O(T / M)

fun combinationSum2(candidates: IntArray, target: Int): List<List<Int>> {
    candidates.sort()
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int, remaining: Int) {
        if (remaining == 0) {
            result.add(ArrayList(path))
            return
        }
        for (i in start until candidates.size) {
            if (candidates[i] > remaining) break
            if (i > start && candidates[i] == candidates[i - 1]) continue   // skip duplicates at this level
            path.add(candidates[i])
            backtrack(i + 1, remaining - candidates[i])                      // i + 1: no reuse
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0, target)
    return result
}
// Time: O(2^n)   Space: O(n)

fun letterCombinations(digits: String): List<String> {
    if (digits.isEmpty()) return emptyList()
    val map = arrayOf("", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz")
    val result = mutableListOf<String>()
    val sb = StringBuilder()

    fun backtrack(i: Int) {
        if (i == digits.length) {
            result.add(sb.toString())
            return
        }
        for (c in map[digits[i] - '0']) {
            sb.append(c)
            backtrack(i + 1)
            sb.deleteCharAt(sb.length - 1)            // undo
        }
    }

    backtrack(0)
    return result
}
// Time: O(4^n * n)   Space: O(n)

fun generateParenthesis(n: Int): List<String> {
    val result = mutableListOf<String>()
    val sb = StringBuilder()

    fun backtrack(open: Int, close: Int) {
        if (sb.length == 2 * n) {
            result.add(sb.toString())
            return
        }
        if (open < n) {                               // can still open
            sb.append('(')
            backtrack(open + 1, close)
            sb.deleteCharAt(sb.length - 1)
        }
        if (close < open) {                           // can close only what is open
            sb.append(')')
            backtrack(open, close + 1)
            sb.deleteCharAt(sb.length - 1)
        }
    }

    backtrack(0, 0)
    return result
}
// Time: O(4^n / sqrt(n)) (Catalan number)   Space: O(n)
// Pruning with the two rules means only valid strings are ever built

fun combinationSum3(k: Int, n: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int, remaining: Int) {
        if (path.size == k) {
            if (remaining == 0) result.add(ArrayList(path))
            return
        }
        for (i in start..9) {
            if (i > remaining) break                  // later digits are even larger
            path.add(i)
            backtrack(i + 1, remaining - i)
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(1, n)
    return result
}
// Time: O(C(9, k) * k)   Space: O(k)

fun partition(s: String): List<List<String>> {
    val result = mutableListOf<List<String>>()
    val path = ArrayList<String>()

    fun isPalindrome(l: Int, r: Int): Boolean {
        var i = l
        var j = r
        while (i < j) {
            if (s[i] != s[j]) return false
            i++
            j--
        }
        return true
    }

    fun backtrack(start: Int) {
        if (start == s.length) {
            result.add(ArrayList(path))
            return
        }
        for (end in start until s.length) {
            if (isPalindrome(start, end)) {           // only cut where the piece is a palindrome
                path.add(s.substring(start, end + 1))
                backtrack(end + 1)
                path.removeAt(path.lastIndex)
            }
        }
    }

    backtrack(0)
    return result
}
// Time: O(n * 2^n)   Space: O(n)
// Precompute a palindrome table with DP to make each check O(1)

fun exist(board: Array<CharArray>, word: String): Boolean {
    val rows = board.size
    val cols = board[0].size

    fun dfs(r: Int, c: Int, i: Int): Boolean {
        if (i == word.length) return true                       // matched every letter
        if (r !in 0 until rows || c !in 0 until cols || board[r][c] != word[i]) return false
        val saved = board[r][c]
        board[r][c] = '#'                                       // mark as used on this path
        val found = dfs(r + 1, c, i + 1) || dfs(r - 1, c, i + 1) ||
                    dfs(r, c + 1, i + 1) || dfs(r, c - 1, i + 1)
        board[r][c] = saved                                     // restore for other paths
        return found
    }

    for (r in 0 until rows) {
        for (c in 0 until cols) {
            if (dfs(r, c, 0)) return true
        }
    }
    return false
}
// Time: O(rows * cols * 3^L)   Space: O(L)

fun solveNQueens(n: Int): List<List<String>> {
    val result = mutableListOf<List<String>>()
    val cols = BooleanArray(n)
    val diag1 = BooleanArray(2 * n)                   // row - col + n identifies a diagonal
    val diag2 = BooleanArray(2 * n)                   // row + col identifies an anti-diagonal
    val queens = IntArray(n)                          // queens[row] = column of that row's queen

    fun backtrack(row: Int) {
        if (row == n) {
            result.add(List(n) { r -> ".".repeat(queens[r]) + "Q" + ".".repeat(n - queens[r] - 1) })
            return
        }
        for (c in 0 until n) {
            val d1 = row - c + n
            val d2 = row + c
            if (cols[c] || diag1[d1] || diag2[d2]) continue     // attacked: prune
            cols[c] = true
            diag1[d1] = true
            diag2[d2] = true
            queens[row] = c
            backtrack(row + 1)
            cols[c] = false                                      // unchoose
            diag1[d1] = false
            diag2[d2] = false
        }
    }

    backtrack(0)
    return result
}
// Time: roughly O(n!)   Space: O(n)
// Boolean arrays make each attack check O(1)

fun solveSudoku(board: Array<CharArray>) {
    val rows = Array(9) { BooleanArray(10) }
    val cols = Array(9) { BooleanArray(10) }
    val boxes = Array(9) { BooleanArray(10) }

    for (r in 0 until 9) {
        for (c in 0 until 9) {
            if (board[r][c] != '.') {
                val d = board[r][c] - '0'
                rows[r][d] = true
                cols[c][d] = true
                boxes[(r / 3) * 3 + c / 3][d] = true
            }
        }
    }

    fun solve(pos: Int): Boolean {
        if (pos == 81) return true                              // every cell is filled
        val r = pos / 9
        val c = pos % 9
        if (board[r][c] != '.') return solve(pos + 1)
        val b = (r / 3) * 3 + c / 3
        for (d in 1..9) {
            if (rows[r][d] || cols[c][d] || boxes[b][d]) continue
            board[r][c] = '0' + d                                // choose
            rows[r][d] = true; cols[c][d] = true; boxes[b][d] = true
            if (solve(pos + 1)) return true                      // stop at the first full solution
            board[r][c] = '.'                                    // unchoose
            rows[r][d] = false; cols[c][d] = false; boxes[b][d] = false
        }
        return false                                             // no digit fits: backtrack
    }

    solve(0)
}
// Time: exponential in the worst case, fast in practice   Space: O(1) extra

fun restoreIpAddresses(s: String): List<String> {
    val result = mutableListOf<String>()
    val parts = ArrayList<String>()

    fun backtrack(start: Int) {
        if (parts.size == 4) {
            if (start == s.length) result.add(parts.joinToString("."))
            return
        }
        for (len in 1..3) {
            if (start + len > s.length) break
            val part = s.substring(start, start + len)
            if (part.length > 1 && part[0] == '0') break         // no leading zeros
            if (part.toInt() > 255) break
            parts.add(part)
            backtrack(start + len)
            parts.removeAt(parts.lastIndex)
        }
    }

    backtrack(0)
    return result
}
// Time: O(3^4) = constant for a bounded input   Space: O(1)

fun canPartitionKSubsets(nums: IntArray, k: Int): Boolean {
    val total = nums.sum()
    if (total % k != 0) return false
    val target = total / k
    nums.sortDescending()                                       // place big numbers first to fail fast
    if (nums[0] > target) return false
    val buckets = IntArray(k)

    fun backtrack(i: Int): Boolean {
        if (i == nums.size) return true
        val tried = HashSet<Int>()                              // symmetry: identical buckets are equivalent
        for (b in 0 until k) {
            if (buckets[b] + nums[i] > target) continue
            if (!tried.add(buckets[b])) continue                // already tried a bucket with this sum
            buckets[b] += nums[i]
            if (backtrack(i + 1)) return true
            buckets[b] -= nums[i]
        }
        return false
    }

    return backtrack(0)
}
// Time: O(k^n) worst case, far less with pruning   Space: O(n)

fun subsetsWithSum(nums: IntArray, target: Int): List<List<Int>> {
    nums.sort()
    val result = mutableListOf<List<Int>>()
    val path = ArrayList<Int>()

    fun backtrack(start: Int, remaining: Int) {
        if (remaining == 0) {
            result.add(ArrayList(path))                         // keep going is unnecessary for positives
            return
        }
        for (i in start until nums.size) {
            if (nums[i] > remaining) break                      // prune: sorted, so all later values are too big
            path.add(nums[i])
            backtrack(i + 1, remaining - nums[i])
            path.removeAt(path.lastIndex)
        }
    }

    backtrack(0, target)
    return result
}
// Assumes positive numbers. Zeros or negatives need a different stopping rule
